class Solution { public String multiply(String a, String b) { if (a.equals("0") || b.equals("0")) return "0"; int[] r = new int[a.length() + b.length()]; for (int i = a.length()-1; i >= 0; i--) for (int j = b.length()-1; j >= 0; j--) { int s = (a.charAt(i)-'0') * (b.charAt(j)-'0') + r[i+j+1]; r[i+j+1] = s % 10; r[i+j] += s / 10; } StringBuilder ans = new StringBuilder(); for (int x : r) if (ans.length() > 0 || x != 0) ans.append(x); return ans.toString(); } }